for(const c of CARDS){
  c.lore={scene:c.symbol,details:c.suit==='major'?MAJOR_DETAILS[c.number]:MINOR_DETAILS[c.suit][c.number-1],history:c.suit==='major'?'這張牌屬於偉特牌的二十二張大牌。偉特在《塔羅圖解之鑰》第二部解說其圖像與象徵。':c.category==='宮廷牌'?'國王、皇后、騎士與侍者延續了早期塔羅四種宮廷人物的架構。偉特牌以姿態、衣飾和場景呈現各花色的性格。':'早期不少數字牌以重複花色符號表現數量；偉特牌在這張牌加入可觀察的情境。《塔羅圖解之鑰》第三部也逐張描述小牌。',source:c.suit==='major'?SOURCES.waiteMajor:SOURCES.waiteMinor};
  if(c.id==='major_08'||c.id==='major_11')c.lore.history+=' 偉特牌採力量第八、正義第十一的編號；不同牌系可能交換這兩張的位置。';
  if(c.suit==='major'){
    const [kind,name,meaning]=MAJOR_ASTRO[c.number];
    c.astro={kind,name,meaning,sign:kind==='zodiac'?name:null,planet:kind==='planet'?name:null,element:kind==='element'?name:kind==='zodiac'?ZODIAC.find(s=>s.name===name).element:c.number===21?'土':null};
  }else if(c.number>=2&&c.number<=10){
    const [sign,planet]=DECANS[c.suit][c.number-2];const decan=(c.number-2)%3;
    c.astro={kind:'decan',name:planet+'・'+sign,sign,planet,element:SUITS[c.suit].element,decan:decan+1,degrees:`${decan*10}°–${(decan+1)*10}°`,meaning:`把${PLANETS.find(p=>p.name===planet).theme}放進${sign}的主題中，再回看「${c.keywords.join('、')}」如何表現在牌面。`};
  }else{
    c.astro={kind:'element',name:SUITS[c.suit].element,sign:null,planet:null,element:SUITS[c.suit].element,meaning:c.number===1?`王牌在這套傳統中代表${SUITS[c.suit].element}元素的根源，不屬於單一星座或十度區間。可從「${SUITS[c.suit].theme}」理解尚待發展的潛力。`:`宮廷牌的星座範圍與角色映射依流派而異。本版以${SUITS[c.suit].element}元素及「${c.name}」的角色觀察，不指定單一星座或行星。`};
  }
  c.search+=' '+[c.astro.name,c.astro.sign,c.astro.planet,c.astro.element].filter(Boolean).join(' ');
}
window.TAROT.ZODIAC=ZODIAC;window.TAROT.PLANETS=PLANETS;window.TAROT.SOURCES=SOURCES;
